/// Whether the query has every pair of a fixed query (`beta=true`).
#[allow(dead_code)]
fn fixed_query(query: &[(String, String)], fixed: &[(&str, &str)]) -> bool {
    fixed
        .iter()
        .all(|(name, value)| query.iter().any(|(k, v)| k == name && v == value))
}

fn error_response(
    status: http::StatusCode,
    error: serde_json::Map<String, serde_json::Value>,
) -> axum::response::Response {
    let mut body = serde_json::Map::new();
    body.insert("error".to_owned(), serde_json::Value::Object(error));
    json_response(status, http::HeaderMap::new(), &body)
}

/// `body` as JSON with this status and these headers; a body that does not serialize is a `500`.
#[allow(dead_code)]
fn json_response<T: serde::Serialize>(
    status: http::StatusCode,
    headers: http::HeaderMap,
    body: &T,
) -> axum::response::Response {
    let (status, bytes) = match serde_json::to_vec(body) {
        Ok(bytes) => (status, bytes),
        Err(_) => (
            http::StatusCode::INTERNAL_SERVER_ERROR,
            br#"{"error":{"message":"the response does not serialize"}}"#.to_vec(),
        ),
    };
    let mut response = axum::response::Response::new(axum::body::Body::from(bytes));
    *response.status_mut() = status;
    response.headers_mut().extend(headers);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        http::HeaderValue::from_static("application/json"),
    );
    response
}

/// An empty body with this status and these headers.
#[allow(dead_code)]
fn empty_response(status: http::StatusCode, headers: http::HeaderMap) -> axum::response::Response {
    let mut response = axum::response::Response::new(axum::body::Body::empty());
    *response.status_mut() = status;
    response.headers_mut().extend(headers);
    response
}

#[allow(dead_code)]
fn status(code: u16) -> http::StatusCode {
    http::StatusCode::from_u16(code).unwrap_or(http::StatusCode::INTERNAL_SERVER_ERROR)
}

#[allow(dead_code)]
fn query_pairs(query: Option<&str>) -> Vec<(String, String)> {
    url::form_urlencoded::parse(query.unwrap_or("").as_bytes())
        .into_owned()
        .collect()
}

/// The path parameter at `key` (its position in the route), `name` in the spec, read by `parse`.
#[allow(dead_code)]
fn path_value<T>(
    path: &std::collections::HashMap<String, String>,
    key: &str,
    name: &str,
    parse: impl Fn(&str) -> Option<T>,
) -> Result<T, RequestError> {
    let value = path
        .get(key)
        .ok_or_else(|| RequestError::new("path", Some(name), "missing"))?;
    parse(value)
        .ok_or_else(|| RequestError::new("path", Some(name), format!("invalid value '{value}'")))
}

/// The first value of the query parameter `name`, read by `parse`; `None` when the query does not have it.
#[allow(dead_code)]
fn query_value<T>(
    query: &[(String, String)],
    name: &str,
    parse: impl Fn(&str) -> Option<T>,
) -> Result<Option<T>, RequestError> {
    match query.iter().find(|(key, _)| key == name) {
        None => Ok(None),
        Some((_, value)) => parse(value).map(Some).ok_or_else(|| {
            RequestError::new("query", Some(name), format!("invalid value '{value}'"))
        }),
    }
}

/// The items of the query parameter `name`: one per occurrence, or the items of its one value split by
/// `separator`, each read by `parse`; `None` when the query does not have it.
#[allow(dead_code)]
fn query_list<T>(
    query: &[(String, String)],
    name: &str,
    separator: Option<&str>,
    parse: impl Fn(&str) -> Option<T>,
) -> Result<Option<Vec<T>>, RequestError> {
    let values: Vec<&str> = query
        .iter()
        .filter(|(key, _)| key == name)
        .map(|(_, value)| value.as_str())
        .collect();
    if values.is_empty() {
        return Ok(None);
    }
    let mut items = Vec::new();
    for value in values {
        let parts: Vec<&str> = match separator {
            Some(separator) if !value.is_empty() => value.split(separator).collect(),
            Some(_) => Vec::new(),
            None => vec![value],
        };
        for part in parts {
            items.push(parse(part).ok_or_else(|| {
                RequestError::new("query", Some(name), format!("invalid item '{part}'"))
            })?);
        }
    }
    Ok(Some(items))
}

/// The deepObject query parameter `name` read into `T`: `name[key]=value`, `name[a][b]=value` for a nested object and
/// `name[a][0]=value` for the items of an array, as the client's `parse_deep_object` writes them. A value is text, read
/// as the type at its place asks (a number, a boolean, `null` for `None`). `None` when the query does not have it.
#[allow(dead_code)]
fn query_deep<T: serde::de::DeserializeOwned>(
    query: &[(String, String)],
    name: &str,
) -> Result<Option<T>, RequestError> {
    let mut root: Option<DeepValue> = None;
    for (key, value) in query {
        let Some(rest) = key.strip_prefix(name) else {
            continue;
        };
        let mut path = Vec::new();
        let mut rest = rest;
        while let Some(inner) = rest.strip_prefix('[') {
            let Some(end) = inner.find(']') else {
                return Err(RequestError::new(
                    "query",
                    Some(name),
                    format!("invalid key '{key}'"),
                ));
            };
            path.push(inner[..end].to_owned());
            rest = &inner[end + 1..];
        }
        if !rest.is_empty() {
            // another parameter whose name starts with this one's
            continue;
        }
        DeepValue::insert(&mut root, &path, value.clone()).map_err(|()| {
            RequestError::new(
                "query",
                Some(name),
                format!("'{key}' conflicts with another key"),
            )
        })?;
    }
    match root {
        None => Ok(None),
        Some(root) => T::deserialize(root)
            .map(Some)
            .map_err(|e| RequestError::new("query", Some(name), e.to_string())),
    }
}

/// The pairs of a deepObject query parameter as a tree: text at the leaves, keys in their order.
#[derive(Debug)]
enum DeepValue {
    Text(String),
    Map(Vec<(String, DeepValue)>),
}

impl DeepValue {
    fn insert(node: &mut Option<DeepValue>, path: &[String], value: String) -> Result<(), ()> {
        let Some((first, rest)) = path.split_first() else {
            return match node {
                None => {
                    *node = Some(DeepValue::Text(value));
                    Ok(())
                }
                Some(_) => Err(()),
            };
        };
        let entries = match node.get_or_insert_with(|| DeepValue::Map(Vec::new())) {
            DeepValue::Map(entries) => entries,
            DeepValue::Text(_) => return Err(()),
        };
        let index = match entries.iter().position(|(key, _)| key == first) {
            Some(index) => index,
            None => {
                entries.push((first.clone(), DeepValue::Map(Vec::new())));
                let index = entries.len() - 1;
                // a new entry starts empty: a leaf or a map, whatever the rest of the path makes it
                let mut child = None;
                DeepValue::insert(&mut child, rest, value)?;
                entries[index].1 = child.unwrap_or(DeepValue::Map(Vec::new()));
                return Ok(());
            }
        };
        let mut child = Some(std::mem::replace(
            &mut entries[index].1,
            DeepValue::Map(Vec::new()),
        ));
        let result = DeepValue::insert(&mut child, rest, value);
        entries[index].1 = child.unwrap_or(DeepValue::Map(Vec::new()));
        result
    }

    fn text(&self) -> Option<&str> {
        match self {
            DeepValue::Text(text) => Some(text),
            DeepValue::Map(_) => None,
        }
    }

    fn parsed<T: std::str::FromStr>(&self, what: &str) -> Result<T, serde::de::value::Error> {
        let text = self
            .text()
            .ok_or_else(|| serde::de::Error::custom(format!("expected {what}, found an object")))?;
        text.parse()
            .map_err(|_| serde::de::Error::custom(format!("expected {what}, found '{text}'")))
    }
}

impl<'de> serde::de::IntoDeserializer<'de, serde::de::value::Error> for DeepValue {
    type Deserializer = Self;

    fn into_deserializer(self) -> Self {
        self
    }
}

