/// A required parameter's value: an error when it is missing.
#[allow(dead_code)]
fn required<T>(location: &'static str, name: &str, value: Option<T>) -> Result<T, RequestError> {
    value.ok_or_else(|| RequestError::new(location, Some(name), "missing"))
}

#[allow(dead_code)]
fn json_body<T: serde::de::DeserializeOwned>(body: &[u8]) -> Result<T, RequestError> {
    if body.iter().all(u8::is_ascii_whitespace) {
        return Err(RequestError::new("body", None, "missing"));
    }
    serde_json::from_slice(body).map_err(|e| RequestError::new("body", None, e.to_string()))
}

#[allow(dead_code)]
fn optional_json_body<T: serde::de::DeserializeOwned>(
    body: &[u8],
) -> Result<Option<T>, RequestError> {
    if body.iter().all(u8::is_ascii_whitespace) {
        return Ok(None);
    }
    // `null` is no body too: what a client sends for one it does not have
    serde_json::from_slice(body).map_err(|e| RequestError::new("body", None, e.to_string()))
}

#[allow(dead_code)]
fn text_body(body: &[u8]) -> Result<String, RequestError> {
    String::from_utf8(body.to_vec()).map_err(|_| RequestError::new("body", None, "not UTF-8"))
}

#[allow(dead_code)]
fn optional_text_body(body: &[u8]) -> Result<Option<String>, RequestError> {
    if body.is_empty() {
        return Ok(None);
    }
    text_body(body).map(Some)
}

#[allow(dead_code)]
fn optional_bytes(body: axum::body::Bytes) -> Option<axum::body::Bytes> {
    (!body.is_empty()).then_some(body)
}

/// `body` as text of this media type, with this status and these headers.
#[allow(dead_code)]
fn text_response(
    status: http::StatusCode,
    headers: http::HeaderMap,
    body: String,
    content_type: &'static str,
) -> axum::response::Response {
    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    *response.status_mut() = status;
    response.headers_mut().extend(headers);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        http::HeaderValue::from_static(content_type),
    );
    response
}

/// A stream of server-sent events, each the JSON of a `T` in a `data:` line, as the client's typed event streams read
/// them; when the spec's event schema has a discriminator, an `event:` line names each event by it (as OpenAI names
/// a Responses stream's events by their `type`). [`EventStream::done`] ends the stream with `data: [DONE]`, for
/// clients that wait for it.
///
/// An error of the stream, or an event that does not serialize, ends the response abruptly: the client sees the body
/// fail, not a clean end.
pub struct EventStream<T> {
    events: std::pin::Pin<Box<dyn futures_util::Stream<Item = Result<T, ServerError>> + Send>>,
    done: bool,
}

impl<T: Send + 'static> EventStream<T> {
    /// The events of `stream`.
    pub fn new<S>(stream: S) -> Self
    where
        S: futures_util::Stream<Item = T> + Send + 'static,
    {
        Self::try_new(futures_util::StreamExt::map(stream, Ok))
    }

    /// The events of `stream`, which can fail: an error ends the response.
    pub fn try_new<S>(stream: S) -> Self
    where
        S: futures_util::Stream<Item = Result<T, ServerError>> + Send + 'static,
    {
        EventStream {
            events: Box::pin(stream),
            done: false,
        }
    }

    /// The events of `events`, all known up front.
    pub fn from_events<I>(events: I) -> Self
    where
        I: IntoIterator<Item = T>,
        I::IntoIter: Send + 'static,
    {
        Self::new(futures_util::stream::iter(events))
    }

    /// Ends the stream with `data: [DONE]` after its events.
    pub fn done(mut self) -> Self {
        self.done = true;
        self
    }
}

impl<T> std::fmt::Debug for EventStream<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EventStream")
            .field("done", &self.done)
            .finish_non_exhaustive()
    }
}

/// A body that is not JSON or text: bytes held in memory or a stream of chunks, sent with the media type the spec
/// declares unless [`Binary::content_type`] sets another.
pub struct Binary {
    body: axum::body::Body,
    content_type: Option<http::HeaderValue>,
}

impl Binary {
    /// Bytes held in memory: the response has a `Content-Length`.
    pub fn bytes(bytes: impl Into<axum::body::Bytes>) -> Self {
        Binary {
            body: axum::body::Body::from(bytes.into()),
            content_type: None,
        }
    }

    /// A stream of chunks, sent as they come (chunked). An error of the stream ends the response abruptly.
    pub fn stream<S, B, E>(stream: S) -> Self
    where
        S: futures_util::Stream<Item = Result<B, E>> + Send + 'static,
        B: Into<axum::body::Bytes> + 'static,
        E: Into<Box<dyn std::error::Error + Send + Sync>> + 'static,
    {
        Binary {
            body: axum::body::Body::from_stream(stream),
            content_type: None,
        }
    }

    /// The media type of the body, instead of the one the spec declares (needed when it declares a range such as
    /// `audio/*`, or more than one). A value that is not a valid header value is ignored.
    pub fn content_type(mut self, content_type: &str) -> Self {
        self.content_type = http::HeaderValue::from_str(content_type).ok();
        self
    }
}

impl From<axum::body::Bytes> for Binary {
    fn from(bytes: axum::body::Bytes) -> Self {
        Binary::bytes(bytes)
    }
}

impl From<Vec<u8>> for Binary {
    fn from(bytes: Vec<u8>) -> Self {
        Binary::bytes(bytes)
    }
}

impl From<&'static [u8]> for Binary {
    fn from(bytes: &'static [u8]) -> Self {
        Binary::bytes(bytes)
    }
}

impl std::fmt::Debug for Binary {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Binary")
            .field("content_type", &self.content_type)
            .finish_non_exhaustive()
    }
}

/// The events of `body` as `text/event-stream`, with this status and these headers; each named by its `name`
/// property (an `event:` line) when there is one.
#[allow(dead_code)]
fn event_stream_response<T: serde::Serialize + Send + 'static>(
    status: http::StatusCode,
    headers: http::HeaderMap,
    body: EventStream<T>,
    name: Option<&'static str>,
) -> axum::response::Response {
    use futures_util::StreamExt;

    type BoxError = Box<dyn std::error::Error + Send + Sync>;
    let done = body.done;
    let events = body
        .events
        .map(move |event| -> Result<axum::body::Bytes, BoxError> {
            let event = event.map_err(|error| error.0)?;
            let mut line = Vec::new();
            if let Some(name) = name {
                // read from its JSON value, then written as it serializes (a value's object keys would be sorted)
                let value = serde_json::to_value(&event)?;
                let named = value.get(name).and_then(serde_json::Value::as_str);
                if let Some(named) = named.filter(|n| !n.contains(['\n', '\r'])) {
                    line.extend_from_slice(b"event: ");
                    line.extend_from_slice(named.as_bytes());
                    line.push(b'\n');
                }
            }
            line.extend_from_slice(b"data: ");
            serde_json::to_writer(&mut line, &event)?;
            line.extend_from_slice(b"\n\n");
            Ok(line.into())
        });
    let end = futures_util::stream::iter(
        done.then(|| Ok::<_, BoxError>(axum::body::Bytes::from_static(b"data: [DONE]\n\n"))),
    );
    let mut response =
        axum::response::Response::new(axum::body::Body::from_stream(events.chain(end)));
    *response.status_mut() = status;
    response.headers_mut().extend(headers);
    response.headers_mut().insert(
        http::header::CONTENT_TYPE,
        http::HeaderValue::from_static("text/event-stream"),
    );
    response.headers_mut().insert(
        http::header::CACHE_CONTROL,
        http::HeaderValue::from_static("no-cache"),
    );
    response
}

/// `body` with this status and these headers, as its own media type or else `content_type`.
#[allow(dead_code)]
fn binary_response(
    status: http::StatusCode,
    headers: http::HeaderMap,
    body: Binary,
    content_type: &'static str,
) -> axum::response::Response {
    let mut response = axum::response::Response::new(body.body);
    *response.status_mut() = status;
    response.headers_mut().extend(headers);
    let content_type = body
        .content_type
        .unwrap_or_else(|| http::HeaderValue::from_static(content_type));
    response
        .headers_mut()
        .insert(http::header::CONTENT_TYPE, content_type);
    response
}

/// The request's media type (`Content-Type` without its parameters, in lower case), if it has one.
#[allow(dead_code)]
fn media_type(headers: &http::HeaderMap) -> Option<String> {
    let value = headers.get(http::header::CONTENT_TYPE)?.to_str().ok()?;
    let essence = value
        .split(';')
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    (!essence.is_empty()).then_some(essence)
}

/// Whether the media type `actual` is one of `declared`: the same, in the range a declared `type/*` or `*/*` covers,
/// or JSON when a declared one is.
#[allow(dead_code)]
fn media_matches(actual: &str, declared: &[&str]) -> bool {
    let json = |m: &str| m.starts_with("application/") && m.contains("json");
    declared.iter().any(|d| {
        *d == actual
            || *d == "*/*"
            || d.strip_suffix("/*")
                .is_some_and(|t| actual.split('/').next() == Some(t))
            || (json(d) && json(actual))
    })
}

/// The whole body of `request`, within axum's limit.
#[allow(dead_code)]
async fn request_bytes(request: axum::extract::Request) -> Result<axum::body::Bytes, RequestError> {
    use axum::extract::FromRequest;

    axum::body::Bytes::from_request(request, &())
        .await
        .map_err(|rejection| {
            RequestError::new("body", None, rejection.body_text()).with_status(rejection.status())
        })
}

/// A file of a `multipart/form-data` request: its bytes, with the file name and media type the client gave.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct FilePart {
    /// The part's file name (`filename` of its `Content-Disposition`), when it has one.
    pub file_name: Option<String>,
    /// The part's `Content-Type`, when it has one.
    pub content_type: Option<String>,
    /// The file.
    pub bytes: axum::body::Bytes,
}

/// One part of a `multipart/form-data` request, or one pair of an `application/x-www-form-urlencoded` one.
struct FormPart {
    name: String,
    file_name: Option<String>,
    content_type: Option<String>,
    bytes: axum::body::Bytes,
}

impl FormPart {
    fn file(&self) -> FilePart {
        FilePart {
            file_name: self.file_name.clone(),
            content_type: self.content_type.clone(),
            bytes: self.bytes.clone(),
        }
    }

    fn text(&self) -> Result<&str, RequestError> {
        std::str::from_utf8(&self.bytes)
            .map_err(|_| RequestError::new("body", Some(&self.name), "not UTF-8"))
    }
}

/// The pairs of an `application/x-www-form-urlencoded` body, as parts.
#[allow(dead_code)]
fn form_pairs(body: &[u8]) -> Vec<FormPart> {
    url::form_urlencoded::parse(body)
        .map(|(name, value)| FormPart {
            name: name.into_owned(),
            file_name: None,
            content_type: None,
            bytes: axum::body::Bytes::from(value.into_owned()),
        })
        .collect()
}

/// The pairs of an `application/x-www-form-urlencoded` body, or `None` for an empty one.
#[allow(dead_code)]
fn optional_form_pairs(body: &[u8]) -> Option<Vec<FormPart>> {
    (!body.is_empty()).then(|| form_pairs(body))
}

/// The parts of a `multipart/form-data` request.
#[allow(dead_code)]
async fn multipart_parts(request: axum::extract::Request) -> Result<Vec<FormPart>, RequestError> {
    use axum::extract::FromRequest;

    let mut multipart = axum::extract::Multipart::from_request(request, &())
        .await
        .map_err(|rejection| RequestError::new("body", None, rejection.body_text()))?;
    let mut parts = Vec::new();
    loop {
        let field = match multipart.next_field().await {
            Ok(Some(field)) => field,
            Ok(None) => return Ok(parts),
            Err(error) => return Err(RequestError::new("body", None, error.body_text())),
        };
        let name = field.name().unwrap_or_default().to_owned();
        let file_name = field.file_name().map(str::to_owned);
        let content_type = field.content_type().map(str::to_owned);
        let bytes = field
            .bytes()
            .await
            .map_err(|error| RequestError::new("body", Some(&name), error.body_text()))?;
        parts.push(FormPart {
            name,
            file_name,
            content_type,
            bytes,
        });
    }
}

/// The parts of a `multipart/form-data` request, or `None` for a request without one.
#[allow(dead_code)]
async fn optional_multipart_parts(
    request: axum::extract::Request,
) -> Result<Option<Vec<FormPart>>, RequestError> {
    let multipart = request
        .headers()
        .get(http::header::CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .is_some_and(|v| {
            v.trim_start()
                .to_ascii_lowercase()
                .starts_with("multipart/")
        });
    if !multipart {
        return Ok(None);
    }
    multipart_parts(request).await.map(Some)
}

/// The first file part named `name`.
#[allow(dead_code)]
fn form_file(parts: &[FormPart], name: &str) -> Option<FilePart> {
    parts.iter().find(|p| p.name == name).map(FormPart::file)
}

/// The file parts named `name`; `None` when there is none.
#[allow(dead_code)]
fn form_files(parts: &[FormPart], name: &str) -> Option<Vec<FilePart>> {
    let files: Vec<FilePart> = parts
        .iter()
        .filter(|p| p.name == name)
        .map(FormPart::file)
        .collect();
    (!files.is_empty()).then_some(files)
}

/// The text of the first part named `name`, read by `parse`; `None` when there is none.
#[allow(dead_code)]
fn form_value<T>(
    parts: &[FormPart],
    name: &str,
    parse: impl Fn(&str) -> Option<T>,
) -> Result<Option<T>, RequestError> {
    match parts.iter().find(|p| p.name == name) {
        None => Ok(None),
        Some(part) => {
            let v = part.text()?;
            parse(v).map(Some).ok_or_else(|| {
                RequestError::new("body", Some(name), format!("invalid value '{v}'"))
            })
        }
    }
}

/// The items of the parts named `name`, read by `parse`: one per part, the items of one part that holds a JSON
/// array (how a client without `multipartHelper` sends a list), or with a `separator` the items of each part split
/// by it (an urlencoded list the client joins); `None` when there is none.
#[allow(dead_code)]
fn form_list<T>(
    parts: &[FormPart],
    name: &str,
    separator: Option<&str>,
    parse: impl Fn(&str) -> Option<T>,
) -> Result<Option<Vec<T>>, RequestError> {
    let named: Vec<&FormPart> = parts.iter().filter(|p| p.name == name).collect();
    let mut texts = Vec::new();
    match named.as_slice() {
        [] => return Ok(None),
        _ if separator.is_some() => {
            let separator = separator.unwrap_or_default();
            for part in named {
                let text = part.text()?;
                if !text.is_empty() {
                    texts.extend(text.split(separator).map(str::to_owned));
                }
            }
        }
        [one] if one.bytes.starts_with(b"[") => {
            let items: Vec<serde_json::Value> = serde_json::from_slice(&one.bytes)
                .map_err(|e| RequestError::new("body", Some(name), e.to_string()))?;
            for item in items {
                texts.push(match item {
                    serde_json::Value::String(text) => text,
                    other => other.to_string(),
                });
            }
        }
        _ => {
            for part in named {
                texts.push(part.text()?.to_owned());
            }
        }
    }
    let mut items = Vec::new();
    for v in texts {
        items.push(
            parse(&v).ok_or_else(|| {
                RequestError::new("body", Some(name), format!("invalid item '{v}'"))
            })?,
        );
    }
    Ok(Some(items))
}

/// The JSON of the first part named `name`; `None` when there is none.
#[allow(dead_code)]
fn form_json<T: serde::de::DeserializeOwned>(
    parts: &[FormPart],
    name: &str,
) -> Result<Option<T>, RequestError> {
    match parts.iter().find(|p| p.name == name) {
        None => Ok(None),
        Some(part) => serde_json::from_slice(&part.bytes)
            .map(Some)
            .map_err(|e| RequestError::new("body", Some(name), e.to_string())),
    }
}

/// The items of the parts named `name`, each JSON: one per part, or the items of one part that holds a JSON array;
/// `None` when there is none.
#[allow(dead_code)]
fn form_json_list<T: serde::de::DeserializeOwned>(
    parts: &[FormPart],
    name: &str,
) -> Result<Option<Vec<T>>, RequestError> {
    let named: Vec<&FormPart> = parts.iter().filter(|p| p.name == name).collect();
    let invalid = |e: serde_json::Error| RequestError::new("body", Some(name), e.to_string());
    match named.as_slice() {
        [] => Ok(None),
        [one] if one.bytes.starts_with(b"[") => serde_json::from_slice(&one.bytes)
            .map(Some)
            .map_err(invalid),
        _ => named
            .iter()
            .map(|part| serde_json::from_slice(&part.bytes).map_err(invalid))
            .collect::<Result<_, _>>()
            .map(Some),
    }
}

/// A part that is not a file as a value of `T`: its JSON, else its text as a string.
#[allow(dead_code)]
fn part_value<T: serde::de::DeserializeOwned>(part: &FormPart) -> Option<T> {
    serde_json::from_slice(&part.bytes).ok().or_else(|| {
        let text = part.text().ok()?;
        serde_json::from_value(serde_json::Value::String(text.to_owned())).ok()
    })
}

