    // A route per operation, each a statement of its own so that a Cargo feature can leave it out.
    #[allow(clippy::let_and_return)]
    pub(super) fn routes<I>(
        router: axum::Router<std::sync::Arc<I>>,
    ) -> axum::Router<std::sync::Arc<I>>
    where
        I: AudioApi + super::ErrorHandler + 'static,
    {
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/speech",
            axum::routing::post(handle_create_speech::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/transcriptions",
            axum::routing::post(handle_create_transcription::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/translations",
            axum::routing::post(handle_create_translation::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voices",
            axum::routing::post(handle_create_voice::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voice_consents",
            axum::routing::post(handle_create_voice_consent::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voices/{p0}",
            axum::routing::delete(handle_delete_voice::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voice_consents/{p0}",
            axum::routing::delete(handle_delete_voice_consent::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voice_consents/{p0}",
            axum::routing::get(handle_get_voice_consent::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voice_consents",
            axum::routing::get(handle_list_voice_consents::<I>),
        );
        #[cfg(feature = "audio")]
        let router = router.route(
            "/audio/voice_consents/{p0}",
            axum::routing::post(handle_update_voice_consent::<I>),
        );
        router
    }

