    // A route per operation, each a statement of its own so that a Cargo feature can leave it out.
    #[allow(clippy::let_and_return)]
    pub(super) fn routes<I>(
        router: axum::Router<std::sync::Arc<I>>,
    ) -> axum::Router<std::sync::Arc<I>>
    where
        I: EvalsApi + super::ErrorHandler + 'static,
    {
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs/{p1}/cancel",
            axum::routing::post(handle_cancel_eval_run::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route("/evals", axum::routing::post(handle_create_eval::<I>));
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs",
            axum::routing::post(handle_create_eval_run::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}",
            axum::routing::delete(handle_delete_eval::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs/{p1}",
            axum::routing::delete(handle_delete_eval_run::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route("/evals/{p0}", axum::routing::get(handle_get_eval::<I>));
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs/{p1}",
            axum::routing::get(handle_get_eval_run::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs/{p1}/output_items/{p2}",
            axum::routing::get(handle_get_eval_run_output_item::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs/{p1}/output_items",
            axum::routing::get(handle_get_eval_run_output_items::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route(
            "/evals/{p0}/runs",
            axum::routing::get(handle_get_eval_runs::<I>),
        );
        #[cfg(feature = "evals")]
        let router = router.route("/evals", axum::routing::get(handle_list_evals::<I>));
        #[cfg(feature = "evals")]
        let router = router.route("/evals/{p0}", axum::routing::post(handle_update_eval::<I>));
        router
    }

