    // A route per operation, each a statement of its own so that a Cargo feature can leave it out.
    #[allow(clippy::let_and_return)]
    pub(super) fn routes<I>(
        router: axum::Router<std::sync::Arc<I>>,
    ) -> axum::Router<std::sync::Arc<I>>
    where
        I: VaultsApi + super::ErrorHandler + 'static,
    {
        #[cfg(feature = "vaults")]
        let router = router.route("/vaults", axum::routing::post(handle_create_vault::<I>));
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}/credentials",
            axum::routing::post(handle_create_vault_credential::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}",
            axum::routing::delete(handle_delete_vault::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}/credentials/{p1}",
            axum::routing::delete(handle_delete_vault_credential::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}/credentials",
            axum::routing::get(handle_list_vault_credentials::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route("/vaults", axum::routing::get(handle_list_vaults::<I>));
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}",
            axum::routing::get(handle_retrieve_vault::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}/credentials/{p1}",
            axum::routing::get(handle_retrieve_vault_credential::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}/credentials/{p1}",
            axum::routing::post(handle_rotate_vault_credential::<I>),
        );
        #[cfg(feature = "vaults")]
        let router = router.route(
            "/vaults/{p0}",
            axum::routing::post(handle_update_vault::<I>),
        );
        router
    }

