    // A route per operation, each a statement of its own so that a Cargo feature can leave it out.
    #[allow(clippy::let_and_return)]
    pub(super) fn routes<I>(
        router: axum::Router<std::sync::Arc<I>>,
    ) -> axum::Router<std::sync::Arc<I>>
    where
        I: VectorStoresApi + super::ErrorHandler + 'static,
    {
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/file_batches/{p1}/cancel",
            axum::routing::post(handle_cancel_vector_store_file_batch::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores",
            axum::routing::post(handle_create_vector_store::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/files",
            axum::routing::post(handle_create_vector_store_file::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/file_batches",
            axum::routing::post(handle_create_vector_store_file_batch::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}",
            axum::routing::delete(handle_delete_vector_store::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/files/{p1}",
            axum::routing::delete(handle_delete_vector_store_file::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}",
            axum::routing::get(handle_get_vector_store::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/files/{p1}",
            axum::routing::get(handle_get_vector_store_file::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/file_batches/{p1}",
            axum::routing::get(handle_get_vector_store_file_batch::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/file_batches/{p1}/files",
            axum::routing::get(handle_list_files_in_vector_store_batch::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/files",
            axum::routing::get(handle_list_vector_store_files::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores",
            axum::routing::get(handle_list_vector_stores::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}",
            axum::routing::post(handle_modify_vector_store::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/files/{p1}/content",
            axum::routing::get(handle_retrieve_vector_store_file_content::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/search",
            axum::routing::post(handle_search_vector_store::<I>),
        );
        #[cfg(feature = "vectorstore")]
        let router = router.route(
            "/vector_stores/{p0}/files/{p1}",
            axum::routing::post(handle_update_vector_store_file_attributes::<I>),
        );
        router
    }

