    // A route per operation, each a statement of its own so that a Cargo feature can leave it out.
    #[allow(clippy::let_and_return)]
    pub(super) fn routes<I>(
        router: axum::Router<std::sync::Arc<I>>,
    ) -> axum::Router<std::sync::Arc<I>>
    where
        I: VideosApi + super::ErrorHandler + 'static,
    {
        #[cfg(feature = "video")]
        let router = router.route("/videos", axum::routing::post(handle_create_video::<I>));
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/characters",
            axum::routing::post(handle_create_video_character::<I>),
        );
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/edits",
            axum::routing::post(handle_create_video_edit::<I>),
        );
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/extensions",
            axum::routing::post(handle_create_video_extend::<I>),
        );
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/{p0}/remix",
            axum::routing::post(handle_create_video_remix::<I>),
        );
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/{p0}",
            axum::routing::delete(handle_delete_video::<I>),
        );
        #[cfg(feature = "video")]
        let router = router.route("/videos/{p0}", axum::routing::get(handle_get_video::<I>));
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/characters/{p0}",
            axum::routing::get(handle_get_video_character::<I>),
        );
        #[cfg(feature = "video")]
        let router = router.route("/videos", axum::routing::get(handle_list_videos::<I>));
        #[cfg(feature = "video")]
        let router = router.route(
            "/videos/{p0}/content",
            axum::routing::get(handle_retrieve_video_content::<I>),
        );
        router
    }

